def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Horizontal colored bars have a hole within the span of same-row cells.
    bars = []
    for r, row in enumerate(g):
        cols = [c for c, v in enumerate(row) if v]
        if len(cols) >= 3:
            color = row[cols[0]]
            if all(row[c] in (0, color) for c in range(cols[0], cols[-1] + 1)):
                bars.append((r, color, cols[0], cols[-1]))
    if not bars:
        return g
    last_r = bars[-1][0]
    # Find vertical marker columns/colors below the final horizontal bar.
    markers = {}
    for c in range(w):
        vals = [g[r][c] for r in range(last_r + 1, h) if g[r][c] != 0]
        if vals:
            markers[c] = vals[-1]
    # At each marker column, horizontal bars crossing its span give successive
    # color bands; the marker color continues below the final crossing.
    for c, marker_color in markers.items():
        crossings = [(r, color) for r, color, left, right in bars
                     if left < c < right and g[r][c] == 0]
        if not crossings:
            continue
        crossings.sort()
        start = 0
        for r, color in crossings:
            for rr in range(start, r + 1):
                g[rr][c] = color
            start = r + 1
        for rr in range(start, h):
            g[rr][c] = marker_color
    return g
